import{_ as a,o as e,c as i,a2 as l}from"./chunks/framework.CHeM0PsO.js";const p=JSON.parse('{"title":"TUI-обозреватель","description":"","frontmatter":{},"headers":[],"relativePath":"ru/advanced/tui.md","filePath":"ru/advanced/tui.md","lastUpdated":1784903584000}'),d={name:"ru/advanced/tui.md"};function o(r,t,s,n,c,h){return e(),i("div",null,[...t[0]||(t[0]=[l('<h1 id="tui-обозреватель" tabindex="-1">TUI-обозреватель <a class="header-anchor" href="#tui-обозреватель" aria-label="Permalink to &quot;TUI-обозреватель&quot;">​</a></h1><h2 id="обзор" tabindex="-1">Обзор <a class="header-anchor" href="#обзор" aria-label="Permalink to &quot;Обзор&quot;">​</a></h2><p>swag2mcp включает встроенный TUI (Terminal User Interface) для интерактивного исследования API. Это полноэкранное терминальное приложение, позволяющее искать, просматривать, проверять и вызывать API-эндпоинты без выхода из терминала.</p><h2 id="запуск" tabindex="-1">Запуск <a class="header-anchor" href="#запуск" aria-label="Permalink to &quot;Запуск&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span></span></code></pre></div><p>Если конфигурационный файл не существует, TUI автоматически запустит мастер инициализации.</p><h2 id="режимы" tabindex="-1">Режимы <a class="header-anchor" href="#режимы" aria-label="Permalink to &quot;Режимы&quot;">​</a></h2><p>TUI имеет три режима, переключаемых клавишей <code>Tab</code>:</p><h3 id="режим-поиска" tabindex="-1">Режим поиска <a class="header-anchor" href="#режим-поиска" aria-label="Permalink to &quot;Режим поиска&quot;">​</a></h3><p>Полнотекстовый поиск по всем эндпоинтам во всех спецификациях. Поддерживает тот же синтаксис запросов, что и MCP-инструмент <code>search</code>.</p><ul><li>Введите запрос для поиска по именам эндпоинтов, путям и описаниям</li><li>Фильтруйте результаты по методу, тегу или пути</li><li>Просматривайте детали эндпоинта одним нажатием клавиши</li><li>Навигируйте по результатам с пагинацией (10 элементов на страницу)</li></ul><h3 id="режим-просмотра" tabindex="-1">Режим просмотра <a class="header-anchor" href="#режим-просмотра" aria-label="Permalink to &quot;Режим просмотра&quot;">​</a></h3><p>Древовидная навигация по иерархии спецификаций:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Спецификация → Коллекция → Тег → Эндпоинт</span></span></code></pre></div><ul><li>Спускайтесь по дереву для поиска конкретных эндпоинтов</li><li>Просматривайте детали эндпоинта (параметры, тело запроса, ответы)</li><li>Вызывайте API напрямую из TUI</li><li>Сохраняйте детали эндпоинта в JSON-файл</li></ul><h3 id="режим-аутентификации" tabindex="-1">Режим аутентификации <a class="header-anchor" href="#режим-аутентификации" aria-label="Permalink to &quot;Режим аутентификации&quot;">​</a></h3><p>Просмотр токенов аутентификации и заголовков для любой спецификации. Полезно для отладки или генерации curl-команд.</p><h2 id="управление" tabindex="-1">Управление <a class="header-anchor" href="#управление" aria-label="Permalink to &quot;Управление&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Клавиша</th><th>Действие</th></tr></thead><tbody><tr><td><code>↑</code> / <code>↓</code></td><td>Навигация вверх/вниз</td></tr><tr><td><code>Enter</code></td><td>Выбрать или открыть</td></tr><tr><td><code>Esc</code></td><td>На один уровень назад</td></tr><tr><td><code>Tab</code></td><td>Переключение между режимами поиска, просмотра и аутентификации</td></tr><tr><td><code>/</code></td><td>Фокус на поле поиска</td></tr><tr><td><code>N</code> / <code>P</code></td><td>Следующая / предыдущая страница</td></tr><tr><td><code>B</code></td><td>Назад к предыдущему экрану</td></tr><tr><td><code>M</code></td><td>Возврат в главное меню</td></tr><tr><td><code>S</code></td><td>Сохранить детали эндпоинта в JSON-файл</td></tr><tr><td><code>q</code> / <code>Ctrl+C</code></td><td>Выход</td></tr></tbody></table><h2 id="состояния" tabindex="-1">Состояния <a class="header-anchor" href="#состояния" aria-label="Permalink to &quot;Состояния&quot;">​</a></h2><p>TUI проходит через следующие состояния по мере навигации:</p><ol><li><strong>Загрузка</strong> — загрузка данных из рабочей области</li><li><strong>Поиск</strong> — режим поиска с полем ввода запроса</li><li><strong>Просмотр</strong> — режим просмотра со списком спецификаций</li><li><strong>Список спецификаций</strong> — список всех спецификаций</li><li><strong>Список коллекций</strong> — коллекции в спецификации</li><li><strong>Список тегов</strong> — теги в коллекции</li><li><strong>Список эндпоинтов</strong> — эндпоинты в теге</li><li><strong>Детали эндпоинта</strong> — полная информация об эндпоинте</li><li><strong>Результат вызова</strong> — результат API-вызова</li><li><strong>Ошибка</strong> — состояние ошибки с сообщением</li></ol><h2 id="просмотр-деталеи-эндпоинта" tabindex="-1">Просмотр деталей эндпоинта <a class="header-anchor" href="#просмотр-деталеи-эндпоинта" aria-label="Permalink to &quot;Просмотр деталей эндпоинта&quot;">​</a></h2><p>При выборе эндпоинта TUI показывает:</p><ul><li>HTTP-метод и путь</li><li>Базовый URL и полный URL</li><li>Описание и сводку</li><li>Все параметры (имя, расположение, тип, обязательность)</li><li>Схему тела запроса (если применимо)</li><li>Коды ответов и схемы</li><li>Статус устаревания</li></ul><h2 id="требования" tabindex="-1">Требования <a class="header-anchor" href="#требования" aria-label="Permalink to &quot;Требования&quot;">​</a></h2><ul><li><strong>Размер терминала:</strong> Не менее 80×24 символов</li><li><strong>Эмулятор терминала:</strong> Работает в большинстве современных терминалов (iTerm2, Terminal.app, GNOME Terminal, Windows Terminal и т.д.)</li><li><strong>SSH:</strong> Работает через SSH-соединения</li></ul><h2 id="важные-замечания" tabindex="-1">Важные замечания <a class="header-anchor" href="#важные-замечания" aria-label="Permalink to &quot;Важные замечания&quot;">​</a></h2><ul><li><strong>Автоинициализация</strong> — если конфигурационный файл не существует, TUI автоматически запускает мастер инициализации</li><li><strong>Пагинация</strong> — списки разбиты на страницы по 10 элементов. Используйте <code>N</code> и <code>P</code> для навигации</li><li><strong>Сохранение деталей эндпоинта</strong> — нажмите <code>S</code> в режиме просмотра деталей эндпоинта, чтобы сохранить полную информацию в JSON-файл в текущей директории</li><li><strong>Режим аутентификации</strong> — показывает токены и заголовки для отладки. В продакшене инструмент аутентификации может быть отключён с помощью <code>--disable-llm-auth</code></li></ul>',29)])])}const g=a(d,[["render",o]]);export{p as __pageData,g as default};
